-- Draft isolated schema: review against the existing database before migration.
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='bc') AND to_regclass('bc.migrations') IS NULL THEN RAISE EXCEPTION 'Schema bc already exists without migration ownership. Inspect existing tables first.'; END IF; END $$;
CREATE SCHEMA IF NOT EXISTS bc;
CREATE TABLE IF NOT EXISTS bc.migrations(version integer PRIMARY KEY,applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS bc.roles(name text PRIMARY KEY,permissions jsonb NOT NULL CHECK(jsonb_typeof(permissions)='array'));
CREATE TABLE IF NOT EXISTS bc.users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),username text NOT NULL,name text NOT NULL,role text NOT NULL REFERENCES bc.roles(name),password_hash text NOT NULL,active boolean NOT NULL DEFAULT true,must_change_password boolean NOT NULL DEFAULT true,notifications boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS users_username_unique ON bc.users(lower(username));
CREATE TABLE IF NOT EXISTS bc.session(sid varchar PRIMARY KEY,sess json NOT NULL,expire timestamp(6) NOT NULL);
CREATE INDEX IF NOT EXISTS session_expire ON bc.session(expire);
CREATE TABLE IF NOT EXISTS bc.processes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,enabled boolean NOT NULL DEFAULT false,config jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS bc.process_versions(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,process_id uuid NOT NULL REFERENCES bc.processes(id),config jsonb NOT NULL,actor_id uuid REFERENCES bc.users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE SEQUENCE IF NOT EXISTS bc.application_number;
CREATE TABLE IF NOT EXISTS bc.applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reference text NOT NULL UNIQUE,process_id uuid NOT NULL REFERENCES bc.processes(id),config jsonb NOT NULL,client_name text NOT NULL,contact text NOT NULL,plot_number text NOT NULL,sector text NOT NULL DEFAULT '',phase text NOT NULL DEFAULT '',submitted_on date NOT NULL,owner_available boolean NOT NULL,representative_name text NOT NULL DEFAULT '',representative_details text NOT NULL DEFAULT '',remarks text NOT NULL DEFAULT '',extra jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'received',assigned_to uuid REFERENCES bc.users(id),created_by uuid NOT NULL REFERENCES bc.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(owner_available OR (length(representative_name)>0 AND length(representative_details)>0)));
CREATE INDEX IF NOT EXISTS applications_status_date ON bc.applications(status,submitted_on);
CREATE INDEX IF NOT EXISTS applications_assignment ON bc.applications(assigned_to,status);
CREATE INDEX IF NOT EXISTS applications_creator ON bc.applications(created_by);
CREATE TABLE IF NOT EXISTS bc.documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),application_id uuid NOT NULL REFERENCES bc.applications(id),requirement_id text,kind text NOT NULL CHECK(kind IN ('requirement','draft','final','acknowledgement')),version integer NOT NULL CHECK(version>0),original_name text NOT NULL,storage_key text NOT NULL UNIQUE,mime text NOT NULL,size integer NOT NULL CHECK(size BETWEEN 1 AND 10485760),superseded boolean NOT NULL DEFAULT false,uploaded_by uuid NOT NULL REFERENCES bc.users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK((kind='requirement')=(requirement_id IS NOT NULL)));
CREATE UNIQUE INDEX IF NOT EXISTS documents_version_unique ON bc.documents(application_id,kind,coalesce(requirement_id,''),version);
CREATE UNIQUE INDEX IF NOT EXISTS documents_current_unique ON bc.documents(application_id,kind,coalesce(requirement_id,'')) WHERE NOT superseded;
CREATE TABLE IF NOT EXISTS bc.scrutiny(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,application_id uuid NOT NULL REFERENCES bc.applications(id),requirement_id text NOT NULL,status text NOT NULL CHECK(status IN ('Received','Verified','Missing','Invalid')),remarks text NOT NULL,actor_id uuid NOT NULL REFERENCES bc.users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS scrutiny_latest ON bc.scrutiny(application_id,requirement_id,created_at DESC,id DESC);
CREATE TABLE IF NOT EXISTS bc.movements(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,application_id uuid NOT NULL REFERENCES bc.applications(id),actor_id uuid NOT NULL REFERENCES bc.users(id),action text NOT NULL,from_status text,to_status text NOT NULL,remarks text NOT NULL DEFAULT '',assigned_to uuid REFERENCES bc.users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS movements_application ON bc.movements(application_id,created_at DESC);
CREATE TABLE IF NOT EXISTS bc.handovers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),application_id uuid NOT NULL UNIQUE REFERENCES bc.applications(id),recipient_name text NOT NULL,verification text NOT NULL,delivered_copy text NOT NULL,retained_copy text NOT NULL,acknowledgement_id uuid NOT NULL REFERENCES bc.documents(id),final_document_id uuid NOT NULL REFERENCES bc.documents(id),actor_id uuid NOT NULL REFERENCES bc.users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS bc.notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES bc.users(id),application_id uuid REFERENCES bc.applications(id),message text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,application_id,message));
CREATE INDEX IF NOT EXISTS notifications_user ON bc.notifications(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS bc.audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id uuid REFERENCES bc.users(id),action text NOT NULL,application_id uuid REFERENCES bc.applications(id),details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_created ON bc.audit(created_at DESC);
CREATE OR REPLACE FUNCTION bc.prevent_history_changes() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Historical records are append-only'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['audit','movements','scrutiny','handovers','process_versions'] LOOP IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgname=t||'_immutable' AND tgrelid=('bc.'||t)::regclass) THEN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON bc.%I FOR EACH ROW EXECUTE FUNCTION bc.prevent_history_changes()',t||'_immutable',t); END IF; END LOOP; END $$;
INSERT INTO bc.migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
